function allow(bucket) {
  const now = Date.now();
  const elapsed = (now - bucket.last) / 1000;
  bucket.tokens = Math.min(
    bucket.cap,
    bucket.tokens + elapsed * bucket.rate
  );
  bucket.last = now;
  if (bucket.tokens < 1) return false;
  bucket.tokens -= 1;
  return true;
}

